package io.ethers.aa

import io.ethers.core.types.Address
import io.ethers.core.types.Hash

/**
 * User operations executed on Ethereum mainnet, with the hashes the EntryPoint emitted for them in
 * `UserOperationEvent`. Recorded by decoding the bundles in `jvmSharedTest/resources/io/ethers/aa/bundles`.
 */
class UserOperationVector(
    val description: String,
    val entryPoint: EntryPoint,
    val chainId: Long,
    val json: String,
    val hash: Hash,
    val eip7702Delegate: Address? = null,
) {
    override fun toString(): String = description
}

